CREATE COLUMN TABLE "TEST_AP"."OIVE" ("TreeID" INTEGER CS_INT DEFAULT 0, "ParentID" INTEGER CS_INT DEFAULT -1, "AbsEntry" INTEGER CS_INT NOT NULL , "LocType" SMALLINT CS_INT, "LocCode" NVARCHAR(8), "TransSeq" INTEGER CS_INT, "LayerID" INTEGER CS_INT, "LayerInQty" DECIMAL(21,6) CS_FIXED, "LayerOutQ" DECIMAL(21,6) CS_FIXED, "LayerVal" DECIMAL(21,6) CS_FIXED, "ItemCode" NVARCHAR(50), "EntryTreeI" INTEGER CS_INT, "LayerCogs" DECIMAL(21,6) CS_FIXED, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."OIVE" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$TransSeq$LayerID$','TransSeq','LayerID'));
CREATE INDEX "OIVE_TRANS_SEQ" ON "TEST_AP"."OIVE" ( "TransSeq" ASC, "LayerID" ASC );
CREATE INDEX "OIVE_TreeID" ON "TEST_AP"."OIVE" ( "TreeID" ASC )